# One controlled backup + restore to a NEW, isolated DB. Never retries a prior
# attempt, uses REPLACE, deletes a file/DB or changes the source permissions.
$ErrorActionPreference='Stop';$root='C:\Users\Xaser\Desktop\ERP';$source=Join-Path $root 'kaynak';$dir=Join-Path $root 'kurulum\first-sale-restore-drill-v1';$connection=$null;$owner=$null;$readerOwner=$null;$stage='PRECHECK'
. (Join-Path $source 'scripts\desktop-empty\first-sale-runner-common.ps1')
function Quote-Sql([string]$value){return "N'"+$value.Replace("'","''")+"'"}
function Read-Json($connection,[string]$sql){$c=$connection.CreateCommand();$c.CommandText=$sql;$c.CommandTimeout=60;$r=$c.ExecuteReader();$b=[Text.StringBuilder]::new();try{while($r.Read()){[void]$b.Append($r.GetString(0))};while($r.NextResult()){while($r.Read()){throw 'EXTRA_RESULT'}}}finally{$r.Dispose();$c.Dispose()};return $b.ToString()|ConvertFrom-Json -AsHashtable}
function Fingerprint([string]$database){
 if($database -cnotmatch '^MELISA_ERP_[A-Z0-9_]+$'){throw 'FINGERPRINT_NAME_REJECTED'}
 return Read-Json $connection @"
DECLARE @result TABLE(tableName nvarchar(128),[rowCount] bigint,dataHash varchar(64));
DECLARE @table sysname,@keys nvarchar(max),@sql nvarchar(max),@json nvarchar(max),@count bigint;
DECLARE tables CURSOR LOCAL FAST_FORWARD FOR SELECT t.name FROM [$database].sys.tables t JOIN [$database].sys.schemas s ON s.schema_id=t.schema_id WHERE t.is_ms_shipped=0 AND s.name=N'dbo' ORDER BY t.name;
OPEN tables;FETCH NEXT FROM tables INTO @table;WHILE @@FETCH_STATUS=0 BEGIN
 SELECT @keys=STRING_AGG(CONVERT(nvarchar(max),QUOTENAME(c.name)),N',') WITHIN GROUP(ORDER BY ic.key_ordinal) FROM [$database].sys.tables t JOIN [$database].sys.schemas s ON s.schema_id=t.schema_id JOIN [$database].sys.indexes i ON i.object_id=t.object_id AND i.is_primary_key=1 JOIN [$database].sys.index_columns ic ON ic.object_id=i.object_id AND ic.index_id=i.index_id JOIN [$database].sys.columns c ON c.object_id=ic.object_id AND c.column_id=ic.column_id WHERE t.name=@table AND s.name=N'dbo';
 IF @keys IS NULL THROW 51995,'FINGERPRINT_PRIMARY_KEY_REQUIRED',1;
 SET @sql=N'SELECT @n=COUNT_BIG(*) FROM [$database].dbo.'+QUOTENAME(@table)+N'; SELECT @j=(SELECT * FROM [$database].dbo.'+QUOTENAME(@table)+N' ORDER BY '+@keys+N' FOR JSON PATH,INCLUDE_NULL_VALUES);';
 EXEC sys.sp_executesql @sql,N'@n bigint OUTPUT,@j nvarchar(max) OUTPUT',@n=@count OUTPUT,@j=@json OUTPUT;
 INSERT @result VALUES(@table,@count,CONVERT(varchar(64),HASHBYTES('SHA2_256',@json),2));FETCH NEXT FROM tables INTO @table;
END;CLOSE tables;DEALLOCATE tables;SELECT tableName,[rowCount],dataHash FROM @result ORDER BY tableName FOR JSON PATH;
"@
}
function Metadata-Hash([string]$database){
 if($database -cnotmatch '^MELISA_ERP_[A-Z0-9_]+$'){throw 'METADATA_NAME_REJECTED'}
 return [string](Read-FirstSaleScalar $connection @"
DECLARE @j nvarchar(max)=(SELECT
 JSON_QUERY((SELECT t.object_id,t.name,t.schema_id FROM [$database].sys.tables t WHERE is_ms_shipped=0 ORDER BY object_id FOR JSON PATH,INCLUDE_NULL_VALUES)) tables,
 JSON_QUERY((SELECT c.object_id,c.column_id,c.name,c.system_type_id,c.user_type_id,c.max_length,c.precision,c.scale,c.collation_name,c.is_nullable,c.is_identity,c.is_computed,c.default_object_id FROM [$database].sys.columns c JOIN [$database].sys.tables t ON t.object_id=c.object_id WHERE t.is_ms_shipped=0 ORDER BY c.object_id,c.column_id FOR JSON PATH,INCLUDE_NULL_VALUES)) columns,
 JSON_QUERY((SELECT i.object_id,i.index_id,i.name,i.type,i.is_unique,i.is_primary_key,i.is_unique_constraint,i.is_disabled,i.has_filter,i.filter_definition FROM [$database].sys.indexes i JOIN [$database].sys.tables t ON t.object_id=i.object_id WHERE t.is_ms_shipped=0 ORDER BY i.object_id,i.index_id FOR JSON PATH,INCLUDE_NULL_VALUES)) indexes,
 JSON_QUERY((SELECT i.object_id,i.index_id,i.index_column_id,i.column_id,i.key_ordinal,i.is_descending_key,i.is_included_column FROM [$database].sys.index_columns i JOIN [$database].sys.tables t ON t.object_id=i.object_id WHERE t.is_ms_shipped=0 ORDER BY i.object_id,i.index_id,i.index_column_id FOR JSON PATH,INCLUDE_NULL_VALUES)) indexColumns,
 JSON_QUERY((SELECT object_id,name,parent_object_id,definition FROM [$database].sys.default_constraints ORDER BY object_id FOR JSON PATH,INCLUDE_NULL_VALUES)) defaults,
 JSON_QUERY((SELECT object_id,name,parent_object_id,definition,is_disabled,is_not_trusted FROM [$database].sys.check_constraints ORDER BY object_id FOR JSON PATH,INCLUDE_NULL_VALUES)) checks,
 JSON_QUERY((SELECT object_id,name,parent_object_id,referenced_object_id,key_index_id,delete_referential_action,update_referential_action,is_disabled,is_not_trusted FROM [$database].sys.foreign_keys ORDER BY object_id FOR JSON PATH,INCLUDE_NULL_VALUES)) foreignKeys,
 JSON_QUERY((SELECT constraint_object_id,constraint_column_id,parent_object_id,parent_column_id,referenced_object_id,referenced_column_id FROM [$database].sys.foreign_key_columns ORDER BY constraint_object_id,constraint_column_id FOR JSON PATH,INCLUDE_NULL_VALUES)) foreignKeyColumns,
 JSON_QUERY((SELECT object_id,definition,uses_ansi_nulls,uses_quoted_identifier,is_schema_bound FROM [$database].sys.sql_modules ORDER BY object_id FOR JSON PATH,INCLUDE_NULL_VALUES)) modules,
 JSON_QUERY((SELECT principal_id,name,type,sid,default_schema_name,owning_principal_id FROM [$database].sys.database_principals WHERE principal_id>4 AND name<>N'public' ORDER BY principal_id FOR JSON PATH,INCLUDE_NULL_VALUES)) principals,
 JSON_QUERY((SELECT role_principal_id,member_principal_id FROM [$database].sys.database_role_members ORDER BY role_principal_id,member_principal_id FOR JSON PATH,INCLUDE_NULL_VALUES)) roleMembers,
 JSON_QUERY((SELECT class,major_id,minor_id,grantee_principal_id,grantor_principal_id,type,state FROM [$database].sys.database_permissions p WHERE NOT(p.class=0 AND p.major_id=0 AND p.minor_id=0 AND p.permission_name=N'CONNECT' AND p.state='D' AND p.grantee_principal_id=(SELECT principal_id FROM [$database].sys.database_principals WHERE name=N'public')) ORDER BY class,major_id,minor_id,grantee_principal_id,grantor_principal_id,type,state FOR JSON PATH,INCLUDE_NULL_VALUES)) permissions
 FOR JSON PATH,WITHOUT_ARRAY_WRAPPER);
SELECT CONVERT(varchar(64),HASHBYTES('SHA2_256',@j),2);
"@)
}
try{
 if(Test-Path -LiteralPath $dir){throw 'PRIOR_ATTEMPT_EXISTS_NO_RETRY'}
 $owner=[IO.File]::Open((Join-Path $root 'desktop-empty-schema.owner.lock'),[IO.FileMode]::OpenOrCreate,[IO.FileAccess]::ReadWrite,[IO.FileShare]::None);$readerOwner=[IO.File]::Open((Join-Path $root 'desktop-initial-reader.owner.lock'),[IO.FileMode]::OpenOrCreate,[IO.FileAccess]::ReadWrite,[IO.FileShare]::None)
 if(@(Get-NetTCPConnection -State Listen -LocalPort 4294,5294 -ErrorAction SilentlyContinue).Count){throw 'APPLICATION_STILL_RUNNING'}
 $connection=Open-FirstSaleAdmin
 $guard=@'
IF DB_ID() IS NULL OR DB_ID()<>5 OR DB_NAME() IS NULL OR CONVERT(varbinary(256),DB_NAME())<>CONVERT(varbinary(256),N'MELISA_ERP_DESKTOP_TEST_20261105') OR SERVERPROPERTY('ProcessID') IS NULL OR SERVERPROPERTY('ServerName') IS NULL OR CONVERT(int,SERVERPROPERTY('ProcessID'))<>5240 OR CONVERT(nvarchar(128),SERVERPROPERTY('ServerName'))<>N'Semih\MELISAERP' OR SUSER_SID() IS NULL OR SUSER_SID(ORIGINAL_LOGIN()) IS NULL OR SUSER_SID(N'SEMIH\Xaser') IS NULL OR SUSER_SID()<>SUSER_SID(N'SEMIH\Xaser') OR SUSER_SID(ORIGINAL_LOGIN())<>SUSER_SID(N'SEMIH\Xaser') OR ISNULL(IS_SRVROLEMEMBER(N'sysadmin'),0)<>1 OR ISNULL(CONVERT(nvarchar(40),CONNECTIONPROPERTY('net_transport')),N'')<>N'Shared memory' OR NOT EXISTS(SELECT 1 FROM sys.database_recovery_status WHERE database_id=5 AND database_guid='c67f5317-9c0d-4831-aadd-fadc379a95d1') OR (SELECT COUNT_BIG(*) FROM dbo.desktop_empty_installation)<>1 OR NOT EXISTS(SELECT 1 FROM dbo.desktop_empty_installation WHERE id=1 AND environment_id='eb2888c2-51cb-4570-a933-397cf7e62806' AND schema_version=2 AND read_only=0 AND actual_t1=0 AND external_operations=0) OR EXISTS(SELECT 1 FROM sys.dm_exec_sessions WHERE is_user_process=1 AND database_id=5 AND session_id<>@@SPID) THROW 51995,'RESTORE_DRILL_SOURCE_REJECTED',1;
'@
 $paths=Read-Json $connection ($guard+"SELECT CONVERT(nvarchar(4000),SERVERPROPERTY('InstanceDefaultBackupPath')) backupDirectory,CONVERT(nvarchar(4000),SERVERPROPERTY('InstanceDefaultDataPath')) dataDirectory,CONVERT(nvarchar(4000),SERVERPROPERTY('InstanceDefaultLogPath')) logDirectory,(SELECT name FROM sys.database_files WHERE type=0) logicalData,(SELECT name FROM sys.database_files WHERE type=1) logicalLog,(SELECT SUM(CONVERT(bigint,size)*8192) FROM sys.database_files) fileBytes,(SELECT COUNT(*) FROM sys.database_files) fileCount FOR JSON PATH,WITHOUT_ARRAY_WRAPPER;")
 if($paths.fileCount -ne 2 -or $paths.fileBytes -le 0){throw 'SOURCE_FILE_LAYOUT_REJECTED'}
 foreach($name in @('backupDirectory','dataDirectory','logDirectory')){if(-not [IO.Path]::IsPathFullyQualified($paths[$name]) -or $paths[$name].StartsWith('\\')){throw 'DIRECTORY_REJECTED'}}
 foreach($name in @('backupDirectory','dataDirectory','logDirectory')){
  $folder=[IO.Path]::GetFullPath($paths[$name]);if([IO.Path]::GetPathRoot($folder) -cne 'C:\'){throw 'CAPACITY_VOLUME_REJECTED'}
  $part=[IO.Path]::GetPathRoot($folder);foreach($segment in $folder.Substring($part.Length).Split('\',[StringSplitOptions]::RemoveEmptyEntries)){$part=Join-Path $part $segment;if(([IO.File]::GetAttributes($part) -band [IO.FileAttributes]::ReparsePoint) -ne 0){throw 'DIRECTORY_REPARSE_REJECTED'}}
 }
 # Same C: volume for backup, restore and CHECKDB. Reserve four complete source
 # file footprints plus 2 GiB, including uncompressed backup and COW snapshot.
 $requiredBytes=[long]$paths.fileBytes*4+2GB;$freeBytes=[long](Get-PSDrive -Name C).Free;if($freeBytes -lt $requiredBytes){throw 'INSUFFICIENT_DISK_CAPACITY'}
 $suffix=[Guid]::NewGuid().ToString('N');$target='MELISA_ERP_RESTORE_CHECK_20261106_'+$suffix.Substring(0,8).ToUpperInvariant();$backup=Join-Path $paths.backupDirectory ('MELISA_ERP_DESKTOP_TEST_20261105_after_first_sale_'+$suffix+'.bak');$data=Join-Path $paths.dataDirectory ($target+'.mdf');$log=Join-Path $paths.logDirectory ($target+'_log.ldf')
 foreach($file in @($backup,$data,$log)){if(Test-Path -LiteralPath $file){throw 'DESTINATION_FILE_EXISTS'}}
 if([int](Read-FirstSaleScalar $connection ("SELECT CASE WHEN DB_ID("+(Quote-Sql $target)+") IS NULL AND NOT EXISTS(SELECT 1 FROM sys.master_files WHERE physical_name IN("+(Quote-Sql $data)+','+(Quote-Sql $log)+")) THEN 1 ELSE 0 END;")) -ne 1){throw 'TARGET_EXISTS'}
 $before=Fingerprint 'MELISA_ERP_DESKTOP_TEST_20261105';$metadataBefore=Metadata-Hash 'MELISA_ERP_DESKTOP_TEST_20261105';if($before.Count -ne 36 -or $metadataBefore -cnotmatch '^[A-F0-9]{64}$'){throw 'SOURCE_FINGERPRINT_REJECTED'};$mediaName='ERP_FIRST_SALE_'+$suffix
 [void][IO.Directory]::CreateDirectory($dir);Write-FirstSaleNew (Join-Path $dir 'attempt.json') @{state='PREPARED';sourceDatabase='MELISA_ERP_DESKTOP_TEST_20261105';sourceGuid='c67f5317-9c0d-4831-aadd-fadc379a95d1';restoreDatabase=$target;backupPath=$backup;dataPath=$data;logPath=$log;sourceFingerprint=$before;sourceMetadataHash=$metadataBefore;capacityRequiredBytes=$requiredBytes;capacityFreeBytes=$freeBytes;time=[DateTime]::UtcNow.ToString('o')}
 $stage='BACKUP';Write-FirstSaleNew (Join-Path $dir 'backup-dispatch.json') @{state='DISPATCHED';time=[DateTime]::UtcNow.ToString('o')}
 $c=$connection.CreateCommand();$c.CommandTimeout=120;$c.CommandText=$guard+"BACKUP DATABASE [MELISA_ERP_DESKTOP_TEST_20261105] TO DISK="+(Quote-Sql $backup)+" WITH COPY_ONLY,CHECKSUM,NO_COMPRESSION,NOINIT,NOSKIP,MEDIANAME="+(Quote-Sql $mediaName)+",NAME="+(Quote-Sql $mediaName)+";RESTORE VERIFYONLY FROM DISK="+(Quote-Sql $backup)+" WITH CHECKSUM,FILE=1,MEDIANAME="+(Quote-Sql $mediaName)+";SELECT N'BACKUP_CHECKSUM_VERIFIED';";try{if($c.ExecuteScalar() -cne 'BACKUP_CHECKSUM_VERIFIED'){throw 'BACKUP_UNCONFIRMED'}}finally{$c.Dispose()}
 $c=$connection.CreateCommand();$c.CommandTimeout=30;$c.CommandText='RESTORE HEADERONLY FROM DISK='+(Quote-Sql $backup)+';';$r=$c.ExecuteReader();try{if(-not $r.Read() -or [int]$r['Position'] -ne 1 -or [string]$r['DatabaseName'] -cne 'MELISA_ERP_DESKTOP_TEST_20261105' -or [string]$r['BackupName'] -cne $mediaName -or [int]$r['BackupType'] -ne 1 -or -not [bool]$r['HasBackupChecksums'] -or -not [bool]$r['IsCopyOnly'] -or $r.Read()){throw 'SINGLE_NEW_BACKUP_SET_REJECTED'}}finally{$r.Dispose();$c.Dispose()}
 Write-FirstSaleNew (Join-Path $dir 'backup-result.json') @{state='BACKUP_CHECKSUM_VERIFIED';time=[DateTime]::UtcNow.ToString('o')}
 $stage='RESTORE';Write-FirstSaleNew (Join-Path $dir 'restore-dispatch.json') @{state='DISPATCHED';time=[DateTime]::UtcNow.ToString('o')}
 $c=$connection.CreateCommand();$c.CommandTimeout=120;$c.CommandText=$guard+"IF DB_ID("+(Quote-Sql $target)+") IS NOT NULL THROW 51995,'RESTORE_TARGET_EXISTS',1;RESTORE DATABASE [$target] FROM DISK="+(Quote-Sql $backup)+" WITH MOVE "+(Quote-Sql $paths.logicalData)+' TO '+(Quote-Sql $data)+',MOVE '+(Quote-Sql $paths.logicalLog)+' TO '+(Quote-Sql $log)+",CHECKSUM,FILE=1,MEDIANAME="+(Quote-Sql $mediaName)+",RECOVERY,RESTRICTED_USER;EXEC [$target].sys.sp_executesql N'DENY CONNECT TO public;';SELECT N'RESTORED_ISOLATED';";try{if($c.ExecuteScalar() -cne 'RESTORED_ISOLATED'){throw 'RESTORE_UNCONFIRMED'}}finally{$c.Dispose()}
 Write-FirstSaleNew (Join-Path $dir 'restore-result.json') @{state='RESTORED_ISOLATED';time=[DateTime]::UtcNow.ToString('o')}
 $stage='VERIFY';$copy=Fingerprint $target;$after=Fingerprint 'MELISA_ERP_DESKTOP_TEST_20261105';$metadataCopy=Metadata-Hash $target;$metadataAfter=Metadata-Hash 'MELISA_ERP_DESKTOP_TEST_20261105'
 $canonical={param($rows)ConvertTo-Json -InputObject @($rows|ForEach-Object{[ordered]@{tableName=$_.tableName;rowCount=$_.rowCount;dataHash=$_.dataHash}}) -Depth 5 -Compress}
 if((& $canonical $before) -cne (& $canonical $copy) -or (& $canonical $before) -cne (& $canonical $after)){throw 'DATA_FINGERPRINT_MISMATCH'}
 if($metadataBefore -cne $metadataCopy -or $metadataBefore -cne $metadataAfter){throw 'SCOPED_METADATA_FINGERPRINT_MISMATCH'}
 $c=$connection.CreateCommand();$c.CommandTimeout=120;$c.CommandText=$guard+"IF DB_ID("+(Quote-Sql $target)+")=5 OR (SELECT COUNT(*) FROM sys.master_files WHERE database_id=DB_ID("+(Quote-Sql $target)+") AND physical_name IN("+(Quote-Sql $data)+','+(Quote-Sql $log)+"))<>2 OR EXISTS(SELECT 1 FROM [$target].sys.foreign_keys WHERE is_disabled=1 OR is_not_trusted=1) OR EXISTS(SELECT 1 FROM [$target].sys.check_constraints WHERE is_disabled=1 OR is_not_trusted=1) THROW 51995,'RESTORED_TARGET_REJECTED',1;EXECUTE AS LOGIN=N'melisa_desktop_test_writer_20261105';DECLARE @access int=HAS_DBACCESS("+(Quote-Sql $target)+");REVERT;IF ISNULL(@access,-1)<>0 THROW 51995,'RESTORED_WRITER_ACCESS_REJECTED',1;DBCC CHECKDB("+(Quote-Sql $target)+") WITH NO_INFOMSGS,ALL_ERRORMSGS;SELECT N'RESTORE_DATA_AND_CHECKDB_VERIFIED';";try{if($c.ExecuteScalar() -cne 'RESTORE_DATA_AND_CHECKDB_VERIFIED'){throw 'CHECKDB_UNCONFIRMED'}}finally{$c.Dispose()}
 Write-FirstSaleNew (Join-Path $dir 'outcome.json') @{state='ACTUAL_RESTORE_DATA_AND_CHECKDB_VERIFIED';restoreDatabase=$target;backupPath=$backup;dataPath=$data;logPath=$log;tables=36;sourceRowDataBeforeEqualsAfter=$true;restoredRowDataEqualsSource=$true;scopedSchemaAndAppSecurityHash=$metadataCopy;copyPublicDenyExcludedFromMetadataComparison=$true;writerCanAccessRestore=$false;oldBackupsModified=$false;sourcePermissionsChanged=$false;restoredApplicationBooted=$false;offMachineCopy=$false;time=[DateTime]::UtcNow.ToString('o')};[Console]::WriteLine('FIRST_SALE_ACTUAL_RESTORE_VERIFIED')
}catch{$native=@();$cursor=$_.Exception;while($cursor){if($cursor -is [Data.Odbc.OdbcException]){$native=@($cursor.Errors|ForEach-Object{$_.NativeError});break};$cursor=$cursor.InnerException};$code=if($_.Exception.Message -cmatch '^[A-Z_]{3,100}$'){$_.Exception.Message}else{'UNCLASSIFIED'};if(Test-Path -LiteralPath $dir){try{Write-FirstSaleNew (Join-Path $dir 'failure.json') @{state='UNKNOWN_NO_RETRY';stage=$stage;code=$code;native=$native;time=[DateTime]::UtcNow.ToString('o')}}catch{}};[Console]::Error.WriteLine("RESTORE_DRILL_STOPPED stage=$stage code=$code native=$($native -join ',')");exit 1}
finally{if($connection){$connection.Dispose()};if($readerOwner){$readerOwner.Dispose()};if($owner){$owner.Dispose()}}
